import {escapeHtml as h,number} from './domain.js';
import {badge,shipArt} from './art.js';
const errorBox='<p class="form-error" role="alert" hidden></p>';
const date=v=>new Date(v).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'});
const percent=v=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(Number(v)||0);
const level=(data,key)=>data?.catalog?.find(c=>c.key===key)?.level||0;
const hidden=(name,value)=>`<input type="hidden" name="${h(name)}" value="${h(value)}">`;
function action(action,label,args={},danger=false){return `<form data-technology="${action}" ${danger?'data-destructive="true"':''}>${Object.entries(args).map(([k,v])=>hidden(k,v)).join('')}<button class="${danger?'danger-button':'secondary'}" type="submit">${label}</button>${errorBox}</form>`;}
function intelView(info){
 let rows=[];if(info.population!=null)rows.push(`<span>Population <b>${number(info.population)}</b></span>`);if('owner'in info)rows.push(`<span>Contrôle <b>${h(info.owner||'Neutre')}</b>${info.clan?` [${h(info.clan)}]`:''}</span>`);if(info.trade_capacity!=null)rows.push(`<span>Capacités <b>${info.trade_capacity}</b></span>`);if(info.energy!=null)rows.push(`<span>Énergie <b>${info.energy} / ${info.energy_max}</b></span>`);if('war'in info)rows.push(`<span>${info.war?'En guerre':'Sans combat'}${info.purifying?' · Purification':''}</span>`);if(info.teleport_access)rows.push('<span class="intel-access">Accès TP obtenu</span>');
 return `<div class="intel-facts">${rows.join('')}</div>${info.civilization_investments?.length?`<p>Assimilation : ${info.civilization_investments.map(j=>`civ ${j.target} · ${date(j.finishes_at)}`).join(' ; ')}</p>`:''}${info.trade_links?.length?`<ul class="intel-links">${info.trade_links.map(l=>`<li>${h(l.planet)} <b>${l.quantity}</b> · ${l.status==='active'?'Active':'En attente'}</li>`).join('')}</ul>`:''}${info.forces?`<div class="intel-forces">${info.forces.filter(f=>Number(f.scouts)+Number(f.bombers)+Number(f.fighters)+Number(f.ground_soldiers)+Number(f.soldiers)>0).map(f=>`<span>${badge('race',f.race)}<b>${f.mission==='attack'?'Attaque':'Défense'}</b>${shipArt(f.race,'scout')}${number(f.scouts)} ${shipArt(f.race,'bomber')}${number(f.bombers)} ${shipArt(f.race,'fighter')}${number(f.fighters)} · ${number(f.ground_soldiers)} au sol · ${number(f.soldiers)} embarqués</span>`).join('')}</div>`:''}${info.infiltrations?`<p>${info.infiltrations.length} infiltration(s) observée(s) : ${info.infiltrations.map(i=>percent(i.level)+' %').join(' · ')||'aucune'}</p>`:''}`;
}
export function planetTechnologyModules(p,data){
 const intel=data?.intelligence,world=intel?.planets?.find(w=>w.id===p.id),special=data?.special?.planets?.find(w=>w.id===p.id),project=special?.project||{},infiltrations=(intel?.infiltrations||[]).filter(i=>i.origin_id===p.id),security=world?.security||{};
 let infiltration=`<section class="planet-technology-module"><h3>Renseignement</h3>`;
 if(!intel?.unlocked)infiltration+='<button class="text-button" data-open-technology>Rechercher l’infiltration →</button>';
 else{
 infiltration+=`<details class="technology-tool"><summary>Infiltrations <b>${infiltrations.length}</b></summary><form data-technology="infiltrate">${hidden('planet_id',p.id)}<label>Planète cible<input type="search" data-infiltration-search placeholder="Rechercher une planète" autocomplete="off"><select name="target_id" data-infiltration-target required>${(world?.targets||[]).slice(0,15).map(t=>`<option value="${h(t.id)}">${h(t.name)}</option>`).join('')}</select></label><label>Objectif <input name="target_level" type="number" min="10" max="100" value="30" required> %</label><button class="secondary" type="submit" ${world?.targets?.length?'':'disabled'}>Infiltrer →</button>${errorBox}</form>${!world?.targets?.length?'<p>Une liaison commerciale ou un historique de contrôle est nécessaire.</p>':''}${infiltrations.map(i=>`<article class="infiltration-card"><header><h4>${h(i.target)}</h4><strong>${percent(i.level)} %</strong></header><progress max="100" value="${i.level}" aria-label="Niveau d’infiltration"></progress><p>${number(i.upkeep)} Þ / jour · objectif ${i.target_level} %</p><form data-technology="infiltration_target">${hidden('infiltration_id',i.id)}<label>Objectif <input type="number" name="target_level" min="10" max="100" value="${i.target_level}" required></label><button class="secondary" type="submit">Ajuster</button>${errorBox}</form>${intelView(i.intel||{})}${Number(i.level)>=90?`<form data-technology="drain">${hidden('infiltration_id',i.id)}<label>Drainage <input type="number" name="rate" min="0" max="${i.intel?.owner?35:70}" value="${Math.round(i.drain*100)}" step="1" required> %</label><button class="secondary" type="submit">Appliquer</button><small>Effectif : ${percent(i.effective_drain*100)} % · modification toutes les 24 h</small>${errorBox}</form>`:''}${action('infiltration_cancel','Abandonner',{infiltration_id:i.id})}</article>`).join('')}</details>`;
 infiltration+=`<details class="technology-tool"><summary>Contre-infiltration <b>${security.mode==='block'?'Blocage':security.mode==='clear'?'Recherche':'Inactive'}</b></summary><form data-technology="security">${hidden('planet_id',p.id)}<label>Protection<select name="mode">${[['off','Désactivée'],['block','Tout bloquer'],['clear','Détecter et nettoyer']].map(([key,label])=>`<option value="${key}" ${security.mode===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Précision <input type="number" name="accuracy" min="1" max="100" value="${security.accuracy||50}" required> %</label><small>Blocage : ${number(2000*p.civilization*(world?.counter_discount||1))} Þ/j · nettoyage : ${number(1000*p.civilization*(world?.counter_discount||1))} Þ/j à 100 %.</small><button class="secondary" type="submit">Appliquer</button>${errorBox}</form></details><details class="technology-tool"><summary>Purification</summary>${security.purifying_until?`<p>Blocus et gel des infiltrations jusqu’au ${date(security.purifying_until)}.</p>${action('purify_cancel','Interrompre',{planet_id:p.id})}`:p.governance==='tyrannie'?`<p>Sept jours de blocus. Vos infiltrations sortantes sont immédiatement perdues.</p>${action('purify','Purifier la planète',{planet_id:p.id})}`:'<p>La purification nécessite la Tyrannie.</p>'}</details>`;
 }
 infiltration+='</section>';
 let powers='<section class="planet-technology-module"><h3>Technologies planétaires</h3>';
 if(level(data,'camouflage'))powers+=action('camouflage',p.camouflaged?'Désactiver le camouflage':'Camoufler les réserves',{planet_id:p.id,enabled:!p.camouflaged});
 if(level(data,'stasis'))powers+=`<details class="technology-tool"><summary>Tranchées stellaires <b>${project.stasis?'Actives':'Inactives'}</b></summary><p>Combats et production de vaisseaux divisés par trois. Activation : 2 charges ; entretien : 1 charge/h, ou 2 sous supériorité ennemie.</p>${action('stasis',project.stasis?'Abaisser':'Déployer',{planet_id:p.id,enabled:!project.stasis})}</details>`;
 if(level(data,'stargate')||project.gate_network)powers+=`<details class="technology-tool"><summary>Porte stellaire</summary>${project.gate_network?`<p>${h(special?.network)} · ${new Date(project.gate_ready_at)>Date.now()?'Connexion au '+date(project.gate_ready_at):'Connectée'} · 1 énergie/h</p>${action('gate_disconnect','Déconnecter',{planet_id:p.id})}`:`<form data-technology="gate_connect">${hidden('planet_id',p.id)}<label>Réseau <input name="network" minlength="3" maxlength="40" required></label><label>Code <input name="password" type="password" minlength="8" maxlength="72" autocomplete="off" required></label><button class="secondary" type="submit">Connecter</button>${errorBox}</form>`}</details>`;
 if(level(data,'black_hole_4'))powers+=`<details class="technology-tool"><summary>Confinement de trou noir</summary>${project.black_hole_ready_at?`<p>${project.black_hole_offensive?'Offensif · ':''}${new Date(project.black_hole_ready_at)>Date.now()?'Préparation jusqu’au '+date(project.black_hole_ready_at):'Confinement prêt'} · 1 énergie/h</p>${new Date(project.black_hole_ready_at)<=Date.now()&&p.governance==='tyrannie'?action('black_hole_activate','Annihiler cette planète',{planet_id:p.id},true):''}${action('black_hole_cancel','Annuler le confinement',{planet_id:p.id})}`:p.governance==='tyrannie'?`${action('black_hole_prepare','Préparer · 48 h',{planet_id:p.id,offensive:false})}${level(data,'black_hole_offensive')?action('black_hole_prepare','Préparer le trou noir offensif · 96 h',{planet_id:p.id,offensive:true}):''}`:'<p>La préparation nécessite la Tyrannie.</p>'}</details>`;
 if(level(data,'energy_blast'))powers+=`<details class="technology-tool"><summary>Onde énergétique</summary><form data-technology="energy_blast">${hidden('planet_id',p.id)}<label>Énergie <input type="number" name="energy" min="1" max="${p.energy}" value="1" required></label><small>Portée : 11,25 unités de distance par charge.</small><button class="secondary" type="submit">Déclencher</button>${errorBox}</form></details>`;
 const scanKinds=['stasis','fleets','armies','trade'].filter(k=>level(data,'scan_'+k));
 if(scanKinds.length)powers+=`<details class="technology-tool"><summary>Scans orbitaux</summary><form data-technology="scan">${hidden('planet_id',p.id)}<label>Cible<select name="target_id" required>${(special?.scan_targets||[]).map(t=>`<option value="${h(t.id)}">${h(t.name)}</option>`).join('')}</select></label><label>Analyse<select name="kind">${scanKinds.map(k=>`<option value="${k}">${({stasis:'Tranchées stellaires',fleets:'Flottes',armies:'Armées',trade:'Commerce'})[k]}</option>`).join('')}</select></label><label>Mode<select name="mode"><option value="basic">Normal · 1 énergie</option><option value="anonymous">Anonyme · 2 énergies</option><option value="stealth">Furtif · 4 énergies</option></select></label><span>80 000 Þ · 4 h</span><button class="secondary" type="submit">Scanner</button>${errorBox}</form></details>`;
 if(project.doom_at)powers+=`<p class="form-error">Cette planète sera absorbée le ${date(project.doom_at)}.</p>`;
 powers+='</section>';
 return `<div class="planet-technology-modules">${infiltration}${powers}</div>`;
}
export function fleetTechnologyControls(f,data){
 if(f.status!=='stationed'||!data)return '';
 const world=data.special?.planets?.find(p=>p.id===f.planet_id),project=world?.project||{};
 return `<div class="fleet-technology-controls"><span>Niveaux : vaisseaux ${percent(f.ship_tech)} · armées ${percent(f.army_tech)}</span>${level(data,'camouflage')?action('camouflage',f.camouflaged?'Révéler les forces':'Camoufler',{fleet_id:f.id,enabled:!f.camouflaged}):''}${level(data,'massive_bombing')&&f.bombers>0?action('massive_bombing',f.massive_bombing?'Bombardement standard':'Bombardement massif',{fleet_id:f.id,enabled:!f.massive_bombing}):''}${project.gate_network&&new Date(project.gate_ready_at)<=Date.now()&&world.gate_targets.length?`<form data-technology="gate_jump">${hidden('fleet_id',f.id)}<label>Porte d’arrivée<select name="target_id">${world.gate_targets.map(p=>`<option value="${h(p.id)}">${h(p.name)}</option>`).join('')}</select></label><label>Mission<select name="mission"><option value="defend">Défense</option><option value="attack">Attaque</option></select></label><button class="secondary" type="submit">Saut · 10 h</button>${errorBox}</form>`:''}</div>`;
}
export function technologyNotificationsView(data,unreadIds=[]){
 const titles={research_complete:'Recherche terminée',purification_complete:'Purification terminée',scan_warning:'Scan détecté',scan_report:'Rapport de scan',black_hole_warning:'Confinement offensif voisin',energy_blast:'Onde énergétique reçue',infiltration_detected:'Captivité détectée'};
 const reports=(data?.reports||[]).filter(r=>titles[r.event]);
 if(!reports.length)return '';
 return `<section class="technology-notifications"><h2>Renseignement & phénomènes stellaires</h2>${reports.map(r=>{const d=r.details||{},v=d.result||{};return `<article class="document-panel ${unreadIds.includes(r.id)?'is-unread':''}"><header><h3>${titles[r.event]} · ${h(r.planet)}</h3><time>${date(r.occurred_at)}</time></header>${d.message?`<p>${h(d.message)}</p>`:''}${d.origin?`<p>Origine : ${h(d.origin)}</p>`:''}${d.ready_at?`<p>Préparation achevée le ${date(d.ready_at)}.</p>`:''}${'stasis'in v?`<p>Tranchées ${v.stasis?'actives':'inactives'}.</p>`:''}${v.approximate_space_power!=null?`<p>Puissance spatiale ≈ ${number(v.approximate_space_power)} (±10 %).</p>`:''}${v.approximate_ground_power!=null?`<p>Puissance terrestre ≈ ${number(v.approximate_ground_power)} (±10 %).</p>`:''}${v.trade_links?`<ul>${v.trade_links.map(l=>`<li>${h(l.planet)} · ${l.quantity} capacités</li>`).join('')}</ul>`:''}${v.destroyed?'<p>Planète détruite.</p>':''}</article>`;}).join('')}</section>`;
}
export function bindIntelligenceSearch(data){document.querySelectorAll('[data-infiltration-search]').forEach(input=>input.oninput=()=>{const form=input.closest('form'),world=data?.intelligence?.planets?.find(p=>p.id===form.elements.planet_id.value),term=input.value.trim().toLocaleLowerCase('fr');form.querySelector('[data-infiltration-target]').innerHTML=(world?.targets||[]).filter(p=>!term||p.name.toLocaleLowerCase('fr').includes(term)).slice(0,15).map(p=>`<option value="${h(p.id)}">${h(p.name)}</option>`).join('');});}
